CREATE NONCLUSTERED INDEX [IX_lines_code] ON [dbo].[lines] ([code] ASC) WITH (PAD_INDEX = OFF, IGNORE_DUP_KEY = OFF, STATISTICS_NORECOMPUTE = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, DATA_COMPRESSION = NONE) ON [PRIMARY];
EXEC [golden_db].sys.sp_addextendedproperty @name = N'MS_Description', @value = N'lookup by code', @level0type = N'SCHEMA', @level0name = N'dbo', @level1type = N'TABLE', @level1name = N'lines', @level2type = N'INDEX', @level2name = N'IX_lines_code';
