EXEC [golden_db].sys.sp_addextendedproperty @name = N'MS_Description', @value = N'key', @level0type = N'SCHEMA', @level0name = N'dbo', @level1type = N'TABLE', @level1name = N'heads', @level2type = N'CONSTRAINT', @level2name = N'PK_heads';
EXEC [golden_db].sys.sp_addextendedproperty @name = N'owner', @value = N'sales', @level0type = N'SCHEMA', @level0name = N'dbo', @level1type = N'TABLE', @level1name = N'heads', @level2type = N'INDEX', @level2name = N'PK_heads';
